// ======================================================
// CUSTOMER FUNCTION SELECTION
//
// true  = customer selected this function
// false = not selected
//
// The LCD only selects the function.
// The PHYSICAL BUTTON starts the timer.
// ======================================================

bool waterSelected  = false;
bool soapSelected   = false;
bool blowerSelected = false;
bool faucetSelected = false;

// ======================================================
// GREEN SELECTION STYLE
//
// These functions add/remove a GREEN outline around
// the selected customer function button.
// ======================================================

static void selectButton(
    lv_obj_t * button
)
{
    if(button == NULL)
        return;

    lv_obj_set_style_border_width(
        button,
        4,
        LV_PART_MAIN
    );

    lv_obj_set_style_border_color(
        button,
        lv_palette_main(LV_PALETTE_GREEN),
        LV_PART_MAIN
    );

    lv_obj_set_style_border_opa(
        button,
        LV_OPA_COVER,
        LV_PART_MAIN
    );
}


static void deselectButton(
    lv_obj_t * button
)
{
    if(button == NULL)
        return;

    lv_obj_set_style_border_width(
        button,
        0,
        LV_PART_MAIN
    );

    lv_obj_set_style_border_opa(
        button,
        LV_OPA_TRANSP,
        LV_PART_MAIN
    );
}


// ======================================================
// CLEAR ALL CUSTOMER SELECTIONS
// ======================================================

static void clearCustomerSelections()
{
    waterSelected  = false;
    soapSelected   = false;
    blowerSelected = false;
    faucetSelected = false;

    deselectButton(ui_waterbtn);
    deselectButton(ui_soapbtn);
    deselectButton(ui_blowerbtn);
    deselectButton(ui_faucetbtn);
}


// ======================================================
// SELECT WATER
// ======================================================

static void selectWater()
{
    clearCustomerSelections();

    waterSelected = true;

    selectButton(ui_waterbtn);

    Serial.println(
        "CUSTOMER SELECTED: WATER"
    );
}

