// ======================================================
// START SCREEN
// ======================================================

void start_clicked(lv_event_t * e)
{
    _ui_screen_change(
        &ui_SelectPaymentpage,
        LV_SCR_LOAD_ANIM_NONE,
        0,
        0,
        &ui_SelectPaymentpage_screen_init
    );
}


// ======================================================
// ADMIN LOGO
// 5 TAPS WITHIN 3 SECONDS
// ======================================================

void admin_logo_clicked(lv_event_t * e)
{
    uint32_t now = millis();

    if(now - lastTapTime > 3000)
    {
        adminTapCount = 0;
    }

    lastTapTime = now;
    adminTapCount++;

    if(adminTapCount >= 5)
    {
        adminTapCount = 0;

        _ui_screen_change(
            &ui_AdminPanel,
            LV_SCR_LOAD_ANIM_NONE,
            0,
            0,
            &ui_AdminPanel_screen_init
        );
    }
}


