// ======================================================
// ADMIN WATER SWITCH
// ======================================================

void water_switch_changed(lv_event_t * e)
{
    lv_obj_t * sw = lv_event_get_target(e);

    if(lv_obj_has_state(sw, LV_STATE_CHECKED))
    {
        setWaterEnabled(true);

        lv_label_set_text(
            ui_PressureStat,
            "ON"
        );

        lv_obj_set_style_text_color(
            ui_PressureStat,
            lv_palette_main(LV_PALETTE_GREEN),
            LV_PART_MAIN
        );
    }
    else
    {
        setWaterEnabled(false);

        // Remove customer selection if disabled
        if(waterSelected)
        {
            waterSelected = false;
            deselectButton(ui_waterbtn);

            lv_label_set_text(
                ui_waterstatus,
                "AVAILABLE"
            );
        }

        lv_label_set_text(
            ui_PressureStat,
            "OFF"
        );

        lv_obj_set_style_text_color(
            ui_PressureStat,
            lv_palette_main(LV_PALETTE_RED),
            LV_PART_MAIN
        );
    }
}


